H.background();
const v = H.plot2d({ xMin: -10, xMax: 10, yMin: -7, yMax: 7 });
v.grid(); v.axes();
const G = 6.674e-11;
const M = 5.972e24;              // Earth mass (kg)
const rScale = Math.max(0.5, P.r);   // orbit radius in Earth radii
const Re = 6.371e6;             // Earth radius (m)
const r = rScale * Re;          // physical orbit radius (m)
const vOrb = Math.sqrt(G * M / r);   // orbital speed (m/s)
// Earth at origin
v.circle(0, 0, 14, { fill: H.colors.accent, stroke: H.colors.ink, width: 1 });
// orbit path radius kept on screen
const Rdisp = Math.min(6, rScale);
const orbit = [];
for (let i = 0; i <= 80; i++) { const a = (i / 80) * Math.PI * 2; orbit.push([Rdisp * Math.cos(a), Rdisp * Math.sin(a)]); }
v.path(orbit, { color: H.colors.grid, width: 1.5, dash: [4, 4] });
// satellite: angular speed scaled so faster (closer) orbits look faster
const omega = 1.2 / Math.sqrt(rScale);
const ang = omega * t;
const sx = Rdisp * Math.cos(ang), sy = Rdisp * Math.sin(ang);
v.dot(sx, sy, { r: 7, fill: H.colors.good });
// velocity vector (tangent to orbit)
v.arrow(sx, sy, sx - 2 * Math.sin(ang), sy + 2 * Math.cos(ang), { color: H.colors.warn, width: 3 });
H.text("Orbital speed:  v = sqrt(G M / r)", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("r = " + rScale.toFixed(1) + " R_Earth = " + (r / 1e6).toFixed(2) + " x10^6 m", 24, 52, { color: H.colors.sub, size: 13 });
H.text("v = " + (vOrb / 1000).toFixed(2) + " km/s", 24, 74, { color: H.colors.sub, size: 13 });
H.legend([{ label: "Earth", color: H.colors.accent }, { label: "satellite", color: H.colors.good }, { label: "velocity v", color: H.colors.warn }], H.W - 180, 28);
